import numpy as np

class Model:
    def __init__(self):
        self.weights = None

    def fit(self, X, y):
        raise NotImplementedError("Subclasses must implement this method")

    def predict(self, X):
        raise NotImplementedError("Subclasses must implement this method")

class LinearModel(Model):
    def __init__(self):
        super().__init__()

    def fit(self, X, y):
        # Simple linear regression with least squares
        self.weights = np.linalg.lstsq(X, y, rcond=None)[0]

    def predict(self, X):
        return X @ self.weights

class RandomModel(Model):
    def __init__(self):
        super().__init__()

    def fit(self, X, y):
        pass

    def predict(self, X):
        return np.random.rand(len(X))

class EpsilonGreedyBandit:
    def __init__(self, models, epsilon=0.1):
        self.models = models
        self.epsilon = epsilon
        self.best_model_index = None
        self.best_model_reward = -np.inf

    def select_arm(self, context):
        if np.random.rand() < self.epsilon:
            arm = np.random.choice(len(self.models))
        else:
            predictions = [model.predict([context])[0] for model in self.models]
            arm = np.argmax(predictions)

        reward = self._get_reward(arm, context)
        self._update_best_model(reward, arm)
        return arm

    def _get_reward(self, arm, context):
        # Simulate getting a reward for the selected arm
        return np.random.normal(loc=self.models[arm].predict([context])[0], scale=1.0)

    def _update_best_model(self, reward, arm):
        if reward > self.best_model_reward:
            self.best_model_reward = reward
            self.best_model_index = arm

# Example usage
