Author: Your Name
*/

// Hook into the 'upgrader_process_complete' action to clear the cache after updates
add_action('upgrader_process_complete', 'clear_nginx_helper_cache_on_update', 10, 2);

function clear_nginx_helper_cache_on_update($upgrader_object, $options) {
    if ($options['action'] == 'update' && in_array($options['type'], array('plugin', 'theme'))) {
        clear_nginx_helper_cache();
    }
}

