function clear_nginx_helper_cache_on_switch_theme() {
    clear_nginx_helper_cache();
}

// Function to clear the Nginx Helper cache
function clear_nginx_helper_cache() {
    // Check if the Nginx Helper plugin is active
    if (is_plugin_active('nginx-helper/nginx-helper.php')) {
        // Call the function provided by the Nginx Helper plugin to clear the cache
        if (function_exists('nginx_helper_clear_cache')) {
