```solidity
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

import "@openzeppelin/contracts/token/ERC1155/ERC1155.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

contract CredToken is ERC1155, Ownable {
    // Define the structure of a credential
    struct Credential {
        string name;
        uint256 expirationDate;
        bool revoked;
    }

    // Mapping to store credentials by ID and owner address
    mapping(uint256 => mapping(address => Credential)) private _credentials;

    // Event emitted when a new credential is issued
    event CredentialIssued(
        uint256 indexed id,
        address indexed owner,
        string name,
        uint256 expirationDate
    );

    // Event emitted when a credential is revoked
    event CredentialRevoked(
        uint256 indexed id,
        address indexed owner,
        string name
    );

    constructor() ERC1155("") {}

    /**
     * @dev Issues a new credential to the specified owner.
     * @param id The unique identifier for the credential.
     * @param owner The address of the owner receiving the credential.
     * @param name The name of the credential.
     * @param expirationDate The expiration date of the credential in seconds since epoch.
     */
    function issueCredential(
        uint256 id,
        address owner,
        string memory name,
        uint256 expirationDate
    ) external onlyOwner {
        require(!isCredentialRevoked(id), "Credential already exists");

        _credentials[id][owner] = Credential(name, expirationDate, false);

        emit CredentialIssued(id, owner, name, expirationDate);
    }

    /**
     * @dev Revokes a credential from the specified owner.
     * @param id The unique identifier for the credential.
     * @param owner The address of the owner whose credential is being revoked.
     */
    function revokeCredential(uint256 id, address owner) external onlyOwner {
        require(isCredentialIssued(id, owner), "Credential does not exist");

        _credentials[id][owner].revoked = true;

        emit CredentialRevoked(id, owner, _credentials[id][owner].name);
    }

    /**
     * @dev Checks if a credential is issued to the specified owner.
     * @param id The unique identifier for the credential.
     * @param owner The address of the owner checking for the credential.
     * @return True if the credential is issued, false otherwise.
     */
    function isCredentialIssued(uint256 id, address owner)
        public
        view
        returns (bool)
    {
        return !isCredentialRevoked(id) && !_credentials[id][owner].revoked;
    }

    /**
     * @dev Checks if a credential is revoked.
     * @param id The unique identifier for the credential.
     * @return True if the credential is revoked, false otherwise.
     */
    function isCredentialRevoked(uint256 id) public view returns (bool) {
        return _credentials[id][address(0)].expirationDate == 0;
    }
}
```

This code defines a `CredToken` contract that inherits from both `ERC1155` and `Ownable`. It includes functions to issue and revoke credentials, as well as events to notify about these actions. The `Credential` struct stores information about each credential, including its name, expiration date, and revocation status.

