Here is an example of a Metal compute kernel that performs Gaussian blurring on an image:

```metal
#include <metal_stdlib>
using namespace metal;

kernel void gaussian_blur(
    texture2d<float, access::read> input [[texture(0)]],
    texture2d<float, access::write> output [[texture(1)]],
    uint2 gid [[thread_position_in_grid]]
) {
    // Define the kernel size and standard deviation for the Gaussian filter
    const int kernelSize = 5;
    const float sigma = 1.0f;

    // Calculate the weights for the Gaussian filter using the formula:
    // w(x) = (1 / sqrt(2 * pi * sigma^2)) * exp(-x^2 / (2 * sigma^2))
    float sumWeights = 0.0f;
    float weights[kernelSize];
    for (int i = 0; i < kernelSize; ++i) {
        float x = i - kernelSize / 2;
        weights[i] = exp(-x * x / (2 * sigma * sigma));
        sumWeights += weights[i];
    }
    for (int i = 0; i < kernelSize; ++i) {
        weights[i] /= sumWeights;
    }

    // Apply the Gaussian filter by convolving with the input image
    float4 result = float4(0.0f);
    for (int y = -kernelSize / 2; y <= kernelSize / 2; ++y) {
        for (int x = -kernelSize / 2; x <= kernelSize / 2; ++x) {
            int sampleY = clamp(gid.y + y, 0, input.get_width() - 1);
            int sampleX = clamp(gid.x + x, 0, input.get_height() - 1);
            result += input.read(int2(sampleX, sampleY)) * weights[y + kernelSize / 2] * weights[x + kernelSize / 2];
        }
    }

    // Write the blurred pixel value to the output texture
    output.write(result, gid);
}
```

This kernel takes two textures as input: `input` contains the original image data, while `output` will store the blurred result. The kernel applies a separable Gaussian filter with a specified kernel size (`kernelSize`) and standard deviation (`sigma`). It calculates the weights for each tap in the filter based on their distance from the center, then convolves these weights with neighboring pixels in both horizontal and vertical directions.

Note that this implementation assumes square images and does not handle edge cases where taps fall outside the bounds of the input image. You may need to modify it depending on your specific use case or requirements.
