```rust
fn main() {
    let mut primes = PrimeStream::new();

    for _ in 0..10 { // Generate first 10 prime numbers
        println!("{}", primes.next().unwrap());
    }
}

struct PrimeStream {
    current: u64,
    limit: Option<u64>,
}

impl PrimeStream {
    fn new() -> Self {
        PrimeStream {
            current: 2,
            limit: None,
        }
    }
}

impl Iterator for PrimeStream {
    type Item = u64;

    fn next(&mut self) -> Option<Self::Item> {
        while !self.is_prime(self.current) {
            self.current += 1;
        }

        if let Some(limit) = &self.limit {
            if self.current > *limit {
                return None;
            }
        }

        let prime = self.current;
        self.current += 1;
        Some(prime)
    }
}

impl PrimeStream {
    fn is_prime(&self, n: u64) -> bool {
        if n <= 1 {
            return false;
        }
        if n == 2 {
            return true;
        }
        if n % 2 == 0 {
            return false;
        }
        let sqrt_n = (n as f64).sqrt() as u64 + 1;
        for i in (3..sqrt_n).step_by(2) {
            if n % i == 0 {
                return false;
            }
        }
        true
    }
}
```

