            if (depth == 0) return;

            var points = GetPoints(100, 10, 300, 10, 200, 200);
            AddTriangle(points);

            foreach (var point in points)
            {
                var subPoints = GetSubPoints(point.X, point.Y, 100, 10, 300, 10, 200, 200);
                GenerateTriangles(depth - 1, subPoints);
            }
        }

        private void AddTriangle(PointCollection points)
