                var startPoint = points[i];
                var endPoint = points[(i + 1) % points.Count];

                var lineGeometry = new LineGeometry(startPoint, endPoint);
                geometryGroup.Children.Add(lineGeometry);
            }

            path.Data = geometryGroup;
            _triangles.Add(path);
        }

        private PointCollection GetPoints(double x1, double y1, double x2, double y2, double x3, double y3)
        {
            return new PointCollection { new Point(x1, y1), new Point(x2, y2), new Point(x3, y3) };
